import{_ as o,o as t,c as n,ag as l}from"./chunks/framework.D7Pdja0E.js";const d=JSON.parse('{"title":"명함을 내 핸드폰 연락처로 동기화","description":"","frontmatter":{},"headers":[],"relativePath":"02-user-guide/crm-phone-sync.md","filePath":"02-user-guide/crm-phone-sync.md","lastUpdated":1780561091000}'),s={name:"02-user-guide/crm-phone-sync.md"};function e(r,a,i,h,u,p){return t(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="명함을-내-핸드폰-연락처로-동기화" tabindex="-1">명함을 내 핸드폰 연락처로 동기화 <a class="header-anchor" href="#명함을-내-핸드폰-연락처로-동기화" aria-label="Permalink to &quot;명함을 내 핸드폰 연락처로 동기화&quot;">​</a></h1><p>워크허브 CRM 에 등록된 외부 담당자(고객사 명함 등) 를 본인 스마트폰의 연락처 앱으로 자동 동기화하는 기능입니다.</p><blockquote><p><strong>단방향 · 본인 선택</strong>: 회사가 직원 핸드폰에 일괄 푸시하는 게 아니라, 직원 본인이 명시적으로 &quot;내 연락처에 추가&quot; 한 담당자만 본인 구글 계정을 거쳐 핸드폰에 등록됩니다. 동료가 본인 핸드폰에 추가한 것은 본인 핸드폰에 안 보입니다 — 각자 별도.</p></blockquote><hr><h2 id="_1-동작-흐름" tabindex="-1">1. 동작 흐름 <a class="header-anchor" href="#_1-동작-흐름" aria-label="Permalink to &quot;1. 동작 흐름&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>워크허브 CRM 담당자 목록 (회사 공유)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │ ① 본인이 체크 → &quot;내 연락처에 추가&quot; 클릭</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>본인 구글 계정의 People API</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │ ② &quot;Workhub — 고객&quot; 라벨 그룹 자동 부여</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>구글 연락처 (contacts.google.com)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │ ③ 핸드폰의 구글 sync 가 자동으로 가져옴</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>본인 스마트폰 연락처 앱</span></span></code></pre></div><p>워크허브 → 구글: 즉시 (1~3초) 구글 → 핸드폰: 1~2분 (sync 주기)</p><hr><h2 id="_2-사전-준비-—-본인-구글-계정-연결-한-번만" tabindex="-1">2. 사전 준비 — 본인 구글 계정 연결 (한 번만) <a class="header-anchor" href="#_2-사전-준비-—-본인-구글-계정-연결-한-번만" aria-label="Permalink to &quot;2. 사전 준비 — 본인 구글 계정 연결 (한 번만)&quot;">​</a></h2><blockquote><p>이미 연결돼 있으면 3번 <a href="#_3-동기화하기">동기화하기</a> 로 넘어가세요.</p></blockquote><h3 id="_1-crm-→-담당자-페이지-진입" tabindex="-1">1) CRM → 담당자 페이지 진입 <a class="header-anchor" href="#_1-crm-→-담당자-페이지-진입" aria-label="Permalink to &quot;1) CRM → 담당자 페이지 진입&quot;">​</a></h3><p><code>/app/crm/contacts</code> 또는 좌측 사이드바 <strong>고객관리 → 담당자</strong> 탭.</p><h3 id="_2-상단-배너의-구글-계정-연결-클릭" tabindex="-1">2) 상단 배너의 &quot;구글 계정 연결&quot; 클릭 <a class="header-anchor" href="#_2-상단-배너의-구글-계정-연결-클릭" aria-label="Permalink to &quot;2) 상단 배너의 &quot;구글 계정 연결&quot; 클릭&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 📱 내 구글 연락처와 연결하면 CRM 담당자를 본인 핸드폰 연락처에  │</span></span>
<span class="line"><span>│    추가할 수 있습니다.                       [구글 계정 연결]  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="_3-본인-google-계정으로-로그인-권한-동의" tabindex="-1">3) 본인 Google 계정으로 로그인 + 권한 동의 <a class="header-anchor" href="#_3-본인-google-계정으로-로그인-권한-동의" aria-label="Permalink to &quot;3) 본인 Google 계정으로 로그인 + 권한 동의&quot;">​</a></h3><p>Google 동의 화면에서:</p><ul><li>본인이 사용 중인 Gmail 계정 선택</li><li>권한: <strong>&quot;연락처 보기 / 추가 / 수정&quot;</strong> 동의</li></ul><blockquote><p>회사가 관리하는 OAuth Client 를 통해 진행되지만, <strong>권한은 본인 계정에만</strong> 적용됩니다. 회사는 본인 구글 계정 자체에 접근하지 못합니다.</p></blockquote><h3 id="_4-연결-완료" tabindex="-1">4) 연결 완료 <a class="header-anchor" href="#_4-연결-완료" aria-label="Permalink to &quot;4) 연결 완료&quot;">​</a></h3><p>배너가 초록색으로 바뀌면 준비 완료:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ ✓ 내 구글 연락처와 연결됨: you@example.com  · 추가된 0건      │</span></span>
<span class="line"><span>│                                                  [연결 해제] │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_3-동기화하기" tabindex="-1">3. 동기화하기 <a class="header-anchor" href="#_3-동기화하기" aria-label="Permalink to &quot;3. 동기화하기&quot;">​</a></h2><h3 id="_1-추가할-담당자-선택" tabindex="-1">1) 추가할 담당자 선택 <a class="header-anchor" href="#_1-추가할-담당자-선택" aria-label="Permalink to &quot;1) 추가할 담당자 선택&quot;">​</a></h3><p>담당자 목록 좌측의 <strong>체크박스</strong> 로 한 명 또는 여러 명 선택.</p><h3 id="_2-상단-액션-바의-버튼-클릭" tabindex="-1">2) 상단 액션 바의 버튼 클릭 <a class="header-anchor" href="#_2-상단-액션-바의-버튼-클릭" aria-label="Permalink to &quot;2) 상단 액션 바의 버튼 클릭&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  2건 선택됨           [선택 해제]  [📱 내 연락처에 추가 (2)]   │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="_3-성공-표시-확인" tabindex="-1">3) 성공 표시 확인 <a class="header-anchor" href="#_3-성공-표시-확인" aria-label="Permalink to &quot;3) 성공 표시 확인&quot;">​</a></h3><ul><li>토스트: &quot;2건 내 구글 연락처에 추가됨&quot;</li><li>추가된 행의 &quot;내 연락처&quot; 열에 <strong>🟢 연결됨</strong> 배지 표시</li></ul><h3 id="_4-핸드폰에-도착-확인" tabindex="-1">4) 핸드폰에 도착 확인 <a class="header-anchor" href="#_4-핸드폰에-도착-확인" aria-label="Permalink to &quot;4) 핸드폰에 도착 확인&quot;">​</a></h3><ul><li>보통 <strong>1~2분 내</strong> 본인 핸드폰 연락처 앱에 자동 표시</li><li>즉시 보고 싶으면 핸드폰 연락처 앱에서 새로고침 (잡아당기기)</li></ul><hr><h2 id="_4-ios-아이폰-설정" tabindex="-1">4. iOS (아이폰) 설정 <a class="header-anchor" href="#_4-ios-아이폰-설정" aria-label="Permalink to &quot;4. iOS (아이폰) 설정&quot;">​</a></h2><p>iOS 는 기본적으로 Google 연락처 sync 가 꺼져 있어 <strong>최초 1회 설정</strong> 이 필요합니다.</p><h3 id="_1-설정-앱-→-연락처" tabindex="-1">1) 설정 앱 → 연락처 <a class="header-anchor" href="#_1-설정-앱-→-연락처" aria-label="Permalink to &quot;1) 설정 앱 → 연락처&quot;">​</a></h3><p>iOS 의 <strong>설정</strong> 앱을 열고 <strong>&quot;연락처&quot;</strong> 메뉴 선택.</p><blockquote><p>iOS 버전에 따라 &quot;메일&quot; 안에 있을 수 있습니다.</p></blockquote><h3 id="_2-계정-→-계정-추가-→-google-선택" tabindex="-1">2) &quot;계정&quot; → &quot;계정 추가&quot; → &quot;Google&quot; 선택 <a class="header-anchor" href="#_2-계정-→-계정-추가-→-google-선택" aria-label="Permalink to &quot;2) &quot;계정&quot; → &quot;계정 추가&quot; → &quot;Google&quot; 선택&quot;">​</a></h3><p>이미 Google 계정이 추가돼 있으면 → <a href="#_5-iOS_-_연락처_토글_ON">그 계정 클릭 → 5번으로</a>.</p><h3 id="_3-워크허브에서-oauth-동의한-그-gmail-계정으로-로그인" tabindex="-1">3) 워크허브에서 OAuth 동의한 그 Gmail 계정으로 로그인 <a class="header-anchor" href="#_3-워크허브에서-oauth-동의한-그-gmail-계정으로-로그인" aria-label="Permalink to &quot;3) 워크허브에서 OAuth 동의한 그 Gmail 계정으로 로그인&quot;">​</a></h3><blockquote><p>이 단계에서 워크허브 연결과 동일한 Gmail 을 선택해야 합니다. 다른 계정을 추가하면 워크허브에서 push 한 연락처가 안 보입니다.</p></blockquote><h3 id="_4-동기화-항목-선택" tabindex="-1">4) 동기화 항목 선택 <a class="header-anchor" href="#_4-동기화-항목-선택" aria-label="Permalink to &quot;4) 동기화 항목 선택&quot;">​</a></h3><ul><li><strong>연락처</strong> 토글 → <strong>ON</strong> (필수)</li><li>메일 / 캘린더 / 메모는 본인 선택</li></ul><h3 id="_5-저장-후-1-2분-대기" tabindex="-1">5) 저장 후 1~2분 대기 <a class="header-anchor" href="#_5-저장-후-1-2분-대기" aria-label="Permalink to &quot;5) 저장 후 1~2분 대기&quot;">​</a></h3><p>핸드폰 <strong>연락처</strong> 앱을 열면 강건욱 등 워크허브에서 추가한 담당자가 표시됩니다.</p><h3 id="그룹별-보기-선택" tabindex="-1">그룹별 보기 (선택) <a class="header-anchor" href="#그룹별-보기-선택" aria-label="Permalink to &quot;그룹별 보기 (선택)&quot;">​</a></h3><p>iOS 연락처 앱 좌상단 <strong>&quot;그룹&quot;</strong> 을 누르면:</p><ul><li>✅ Gmail → <strong>Workhub — 고객</strong> (워크허브에서 추가한 담당자만)</li><li>✅ 다른 항목 모두 해제</li></ul><p>→ 회사 명함과 개인 연락처가 깔끔히 분리되어 보입니다.</p><h3 id="안-보일-때-점검" tabindex="-1">안 보일 때 점검 <a class="header-anchor" href="#안-보일-때-점검" aria-label="Permalink to &quot;안 보일 때 점검&quot;">​</a></h3><ol><li><strong>설정 → 연락처 → 계정 → Gmail → &quot;연락처&quot; 토글이 켜져 있나?</strong><ul><li>꺼져 있으면 켜고 1~2분 기다림</li></ul></li><li><strong>연락처 앱에서 위에서 아래로 잡아당겨 새로고침</strong></li><li><strong>그래도 안 보이면</strong> — 설정에서 &quot;연락처&quot; 토글 OFF → ON (재동기화 강제)</li><li><strong>본인 Google 계정에는 등록됐는지</strong> 먼저 확인: <ul><li>사파리에서 <a href="https://contacts.google.com" target="_blank" rel="noreferrer">https://contacts.google.com</a> 접속</li><li>좌측 라벨 &quot;<strong>Workhub — 고객</strong>&quot; 그룹에 해당 담당자가 있어야 함</li></ul></li></ol><hr><h2 id="_5-android-설정" tabindex="-1">5. Android 설정 <a class="header-anchor" href="#_5-android-설정" aria-label="Permalink to &quot;5. Android 설정&quot;">​</a></h2><p>Android 는 보통 본인 Google 계정의 연락처 sync 가 <strong>기본 활성</strong>이라 별도 설정 불필요합니다. 워크허브에서 추가하면 1~2분 내 핸드폰에 표시됩니다.</p><h3 id="만약-안-보이면" tabindex="-1">만약 안 보이면 <a class="header-anchor" href="#만약-안-보이면" aria-label="Permalink to &quot;만약 안 보이면&quot;">​</a></h3><ol><li><strong>설정</strong> → <strong>계정</strong> (또는 &quot;사용자 및 계정&quot;)</li><li><strong>Google</strong> → 사용 중인 Gmail 계정 선택</li><li><strong>계정 동기화</strong> → <strong>연락처</strong> 토글 ON</li><li>우상단 메뉴 (⋮) → <strong>&quot;지금 동기화&quot;</strong> 누르기</li></ol><h3 id="그룹별-보기-pixel-삼성" tabindex="-1">그룹별 보기 (Pixel/삼성) <a class="header-anchor" href="#그룹별-보기-pixel-삼성" aria-label="Permalink to &quot;그룹별 보기 (Pixel/삼성)&quot;">​</a></h3><ul><li>Google 연락처 앱 (별도 설치): 좌상단 ☰ → &quot;라벨&quot; → <strong>Workhub — 고객</strong></li><li>삼성 연락처 앱: 좌상단 ☰ → &quot;라벨&quot; 또는 &quot;그룹&quot; → <strong>Workhub — 고객</strong></li></ul><hr><h2 id="_6-자주-묻는-질문-faq" tabindex="-1">6. 자주 묻는 질문 (FAQ) <a class="header-anchor" href="#_6-자주-묻는-질문-faq" aria-label="Permalink to &quot;6. 자주 묻는 질문 (FAQ)&quot;">​</a></h2><h3 id="q-동료가-내-핸드폰에-추가하면-내-연락처에도-보이나요" tabindex="-1">Q. 동료가 내 핸드폰에 추가하면 내 연락처에도 보이나요? <a class="header-anchor" href="#q-동료가-내-핸드폰에-추가하면-내-연락처에도-보이나요" aria-label="Permalink to &quot;Q. 동료가 내 핸드폰에 추가하면 내 연락처에도 보이나요?&quot;">​</a></h3><p><strong>아니요.</strong> 각 직원이 본인 핸드폰에 따로 추가해야 합니다.</p><ul><li>A 직원이 &quot;내 연락처에 추가&quot; → <strong>A 핸드폰만</strong> 등록</li><li>B 직원이 같은 담당자를 본인 핸드폰에 받으려면 → <strong>B 도 직접 체크 → 추가</strong></li></ul><p>회사의 마스터 데이터(이름·전화·이메일)는 공유되지만, 핸드폰에 가져가는 건 각자의 선택입니다.</p><h3 id="q-회사가-내-핸드폰의-다른-연락처를-볼-수-있나요" tabindex="-1">Q. 회사가 내 핸드폰의 다른 연락처를 볼 수 있나요? <a class="header-anchor" href="#q-회사가-내-핸드폰의-다른-연락처를-볼-수-있나요" aria-label="Permalink to &quot;Q. 회사가 내 핸드폰의 다른 연락처를 볼 수 있나요?&quot;">​</a></h3><p><strong>볼 수 없습니다.</strong></p><ul><li>동의한 권한은 <strong>&quot;내가 연락처를 추가/수정&quot;</strong> 만</li><li>본인이 직접 등록하지 않은 연락처는 워크허브가 읽을 수 없음</li><li>&quot;Workhub — 고객&quot; 라벨 그룹의 항목만 워크허브가 추적</li></ul><h3 id="q-담당자-정보가-워크허브에서-바뀌면-핸드폰에도-반영되나요" tabindex="-1">Q. 담당자 정보가 워크허브에서 바뀌면 핸드폰에도 반영되나요? <a class="header-anchor" href="#q-담당자-정보가-워크허브에서-바뀌면-핸드폰에도-반영되나요" aria-label="Permalink to &quot;Q. 담당자 정보가 워크허브에서 바뀌면 핸드폰에도 반영되나요?&quot;">​</a></h3><p>지금은 <strong>자동 갱신 안 됨</strong>. 변경 후 다시 &quot;내 연락처에 추가&quot; 누르면 갱신됩니다.</p><blockquote><p>향후 자동 갱신 기능을 검토 중입니다.</p></blockquote><h3 id="q-연결-해제-누르면-핸드폰-연락처도-지워지나요" tabindex="-1">Q. &quot;연결 해제&quot; 누르면 핸드폰 연락처도 지워지나요? <a class="header-anchor" href="#q-연결-해제-누르면-핸드폰-연락처도-지워지나요" aria-label="Permalink to &quot;Q. &quot;연결 해제&quot; 누르면 핸드폰 연락처도 지워지나요?&quot;">​</a></h3><p><strong>아니요.</strong></p><ul><li>&quot;연결 해제&quot; = 워크허브 ↔ 본인 Google 계정의 <strong>OAuth 토큰만 끊음</strong></li><li>본인 Google 연락처에 이미 등록된 사람은 그대로 보존</li><li>새로운 동기화만 중단</li></ul><p>핸드폰에서 지우려면 Google 연락처 (<a href="https://contacts.google.com" target="_blank" rel="noreferrer">https://contacts.google.com</a>) 에서 &quot;Workhub — 고객&quot; 라벨 일괄 삭제.</p><h3 id="q-한-담당자를-핸드폰에서-빼고-싶으면" tabindex="-1">Q. 한 담당자를 핸드폰에서 빼고 싶으면? <a class="header-anchor" href="#q-한-담당자를-핸드폰에서-빼고-싶으면" aria-label="Permalink to &quot;Q. 한 담당자를 핸드폰에서 빼고 싶으면?&quot;">​</a></h3><p>워크허브 담당자 목록에서:</p><ul><li>그 사람 행의 <strong>✓ 연결됨</strong> 배지 클릭 → 확인</li><li>본인 Google 연락처에서 삭제 + 핸드폰 sync 까지 1~2분 내 자동 반영</li></ul><h3 id="q-퇴사하면-내-핸드폰-연락처는-어떻게-되나요" tabindex="-1">Q. 퇴사하면 내 핸드폰 연락처는 어떻게 되나요? <a class="header-anchor" href="#q-퇴사하면-내-핸드폰-연락처는-어떻게-되나요" aria-label="Permalink to &quot;Q. 퇴사하면 내 핸드폰 연락처는 어떻게 되나요?&quot;">​</a></h3><ul><li><strong>본인 Google 계정의 연락처는 그대로 보존</strong> (개인 자산)</li><li>워크허브 측 sync 만 중단 (OAuth 토큰 자동 회수)</li><li>핸드폰에 이미 있는 강건욱 등은 그대로 — 본인이 정리 원하면 위의 &quot;Workhub — 고객&quot; 라벨 일괄 삭제</li></ul><h3 id="q-다른-사람의-명함을-내-연락처에-추가한-게-회사에-보이나요" tabindex="-1">Q. 다른 사람의 명함을 내 연락처에 추가한 게 회사에 보이나요? <a class="header-anchor" href="#q-다른-사람의-명함을-내-연락처에-추가한-게-회사에-보이나요" aria-label="Permalink to &quot;Q. 다른 사람의 명함을 내 연락처에 추가한 게 회사에 보이나요?&quot;">​</a></h3><p>회사 관리자에게 <strong>누가 어떤 담당자를 본인 폰에 추가했는지</strong> 는 보이지 않습니다 (audit 외부 노출 안 함). 본인 화면에서만 자기 sync 상태가 보입니다.</p><hr><h2 id="_7-보안-개인정보" tabindex="-1">7. 보안 / 개인정보 <a class="header-anchor" href="#_7-보안-개인정보" aria-label="Permalink to &quot;7. 보안 / 개인정보&quot;">​</a></h2><ul><li>권한 동의는 <strong>본인 Google 계정</strong> 기준 — 회사 관리자도 본인 권한을 변경/회수할 수 없음</li><li>워크허브에 저장되는 정보: OAuth refresh token (AES-GCM 암호화), 연결된 contact ID 매핑</li><li>본인이 언제든 <a href="https://myaccount.google.com/permissions" target="_blank" rel="noreferrer">https://myaccount.google.com/permissions</a> 에서 워크허브 권한 회수 가능 → 즉시 sync 중단</li><li>회수 후 다시 사용하려면 <strong>사전 준비 2번</strong> 부터 재진행</li></ul><hr><h2 id="관련-가이드" tabindex="-1">관련 가이드 <a class="header-anchor" href="#관련-가이드" aria-label="Permalink to &quot;관련 가이드&quot;">​</a></h2><ul><li><a href="./contacts.html">연락처(사내 주소록)</a> — 사내 동료 연락처 (CRM 명함과 별개)</li><li><a href="./messaging.html">메시지</a></li><li><a href="./tasks.html">태스크</a></li></ul>`,87)])])}const q=o(s,[["render",e]]);export{d as __pageData,q as default};
